// Incremental sync via jobs_seen_after. We persist the last sync
// timestamp in n8n's static workflow data — keyed by domain so multiple
// domains can share this template.
//
// First run: jobs_seen_after is unset → returns the most recent jobs
// (capped by jobs_limit). Subsequent runs only emit jobs whose
// first_seen_at is at or after the last successful sync time.

const { domain } = $input.first().json;
const apiKey = $env.SUBSPACE_API_KEY;
if (!apiKey) {
  throw new Error("Missing API key. Set SUBSPACE_API_KEY in your n8n environment, or hard-code the key in this Code node.");
}

// Load last-sync per domain from workflow static data
const staticData = $getWorkflowStaticData('global');
staticData.lastSeenByDomain ??= {};
const lastSeen = staticData.lastSeenByDomain[domain] || null;

const url = new URL('https://www.thesubspace.io/api/v1/enrich');
url.searchParams.set('domain', domain);
url.searchParams.set('include', 'jobs');
url.searchParams.set('jobs_limit', '500'); // cap per run; if you need more, paginate via offset
if (lastSeen) {
  url.searchParams.set('jobs_seen_after', lastSeen);
}

const res = await this.helpers.httpRequest({
  method: 'GET',
  url: url.toString(),
  headers: { 'x-api-key': apiKey },
  json: true,
});

const jobs = res.jobs || [];

// Update high-water mark to NOW (rather than max(first_seen_at)) so
// we don't double-emit if upstream backfills late. Trade-off: a job
// added at 12:00:01 right after a 12:00:00 poll waits for the next tick.
staticData.lastSeenByDomain[domain] = new Date().toISOString();

return jobs.map(j => ({ json: { ...j, company_domain: domain, sync_at: staticData.lastSeenByDomain[domain] } }));
